package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanRec LoanRec

// file handling for LINE SEQUENTIAL
var loanFileLines []string
var loanFileIndex int
var loanFileOpen bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func truncateToScale(d decimal.Decimal, scale int32, integerDigits int) decimal.Decimal {
	// keep only low-order digits that fit: total digits = integerDigits + scale
	// implemented as modulo 10^(integerDigits+scale) on unscaled value
	if integerDigits < 0 {
		return d
	}
	totalDigits := int64(integerDigits) + int64(scale)
	// 10^totalDigits as decimal
	pow10 := decimal.NewFromInt(1)
	ten := decimal.NewFromInt(10)
	for i := int64(0); i < totalDigits; i++ {
		pow10 = pow10.Mul(ten)
	}
	// unscaled = d * 10^scale
	scalePow := decimal.NewFromInt(1)
	for i := int32(0); i < scale; i++ {
		scalePow = scalePow.Mul(ten)
	}
	unscaled := d.Mul(scalePow)
	// truncate toward zero for integer representation
	unscaledTrunc := unscaled.Truncate(0)
	// modulo pow10 keeping sign
	// For positive numbers modulus is remainder; for this program values are non-negative
	// Use IntPart and manual mod via decimal
	// pow10 fits within 10^13 < 2^63, safe for int64? But use decimal remainder
	// unscaledTrunc = trunc(unscaledTrunc / pow10)*pow10 + rem
	// rem = unscaledTrunc - trunc(unscaledTrunc/pow10)*pow10
	q := unscaledTrunc.Div(pow10).Truncate(0)
	rem := unscaledTrunc.Sub(q.Mul(pow10))
	// reconstruct
	return rem.Div(scalePow)
}

func formatEdited(value decimal.Decimal, picture string) string {
	// picture contains Z,9,',','.' and maybe other literals
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	// count integer slots Z+9
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracDigits := len(fracPic) // number of 9 after decimal, assumed all 9

	// integer part absolute
	// value is already at scale, but to be safe
	intPart := value.Truncate(0)
	if intPart.IsNegative() {
		intPart = intPart.Neg()
	}
	// also need frac part
	// Build frac string with exactly fracDigits digits
	// Use absolute value
	absVal := value
	if absVal.IsNegative() {
		absVal = absVal.Neg()
	}
	// Extract integer and fractional digits
	// Integer digits modulo 10^intSlots (high-order truncation)
	if intSlots > 0 {
		// overflow handling: keep low-order intSlots digits
		modPow := int64(1)
		for i := 0; i < intSlots; i++ {
			modPow *= 10
		}
		// intPartInt as int64 may overflow for 11 digits (20B fits)
		ip := intPart.IntPart()
		if ip < 0 {
			ip = -ip
		}
		// use modulo on int64 (since intSlots <=11 fits)
		rem := ip % modPow
		intPart = decimal.NewFromInt(rem)
	}
	// Build integer digits string zero padded to intSlots
	ipInt := intPart.IntPart()
	intDigits := fmt.Sprintf("%0*d", intSlots, ipInt)
	// In case ipInt had more digits than intSlots already modded, length == intSlots
	if len(intDigits) > intSlots {
		intDigits = intDigits[len(intDigits)-intSlots:]
	}

	// Build output for integer part with same length as intPic
	outInt := make([]rune, len(intPic))
	picRunes := []rune(intPic)
	digitIdx := 0
	// first pass place digits and commas
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			outInt[i] = rune(intDigits[digitIdx])
			digitIdx++
		} else if ch == ',' {
			outInt[i] = ','
		} else {
			outInt[i] = ch
		}
	}
	// second pass suppression
	// find positions of digit slots
	suppressed := true
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			if suppressed {
				if outInt[i] == '0' {
					if ch == 'Z' {
						outInt[i] = ' '
					} else {
						// '9' mandatory zero, end suppression
						suppressed = false
					}
				} else {
					suppressed = false
				}
			}
		}
	}
	// commas inside suppressed zone become spaces: any comma before first non-space digit
	firstNonSpaceDigitPos := -1
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			if outInt[i] != ' ' {
				firstNonSpaceDigitPos = i
				break
			}
		}
	}
	if firstNonSpaceDigitPos == -1 {
		// all spaces except maybe mandatory 0; firstNonSpace is the mandatory 9 position
		// commas all become spaces? But if integer is zero, we still have a '0' at mandatory position
		// Find that mandatory 0
		for i := range outInt {
			if outInt[i] == '0' {
				firstNonSpaceDigitPos = i
				break
			}
		}
	}
	if firstNonSpaceDigitPos != -1 {
		for i, ch := range picRunes {
			if ch == ',' {
				if i < firstNonSpaceDigitPos {
					outInt[i] = ' '
				}
			}
		}
	} else {
		// all suppressed (should not happen because of 9)
		for i, ch := range picRunes {
			if ch == ',' {
				outInt[i] = ' '
			}
		}
	}

	result := string(outInt)
	if dotIdx >= 0 {
		result += "."
		// fractional part: absVal * 10^fracDigits fractional
		// Extract fractional digits zero padded
		// absVal scaled
		// Use decimal arithmetic to get exactly fracDigits
		// frac = (absVal - intPartAbs) * 10^fracDigits rounded already
		// Simpler: format absVal with scale fracDigits, take after decimal
		// Ensure absVal has fracDigits scale
		// Use StringFixed or get fractional
		// We'll compute: shifted = absVal * 10^fracDigits truncated
		shiftPow := decimal.NewFromInt(1)
		for i := 0; i < fracDigits; i++ {
			shiftPow = shiftPow.Mul(decimal.NewFromInt(10))
		}
		shifted := absVal.Mul(shiftPow).Truncate(0)
		// fractional part is shifted % 10^fracDigits
		mod := int64(1)
		for i := 0; i < fracDigits; i++ {
			mod *= 10
		}
		fracInt := shifted.IntPart() % mod
		if fracInt < 0 {
			fracInt = -fracInt
		}
		fracStr := fmt.Sprintf("%0*d", fracDigits, fracInt)
		result += fracStr
	}
	return result
}

func formatPrinEd(d decimal.Decimal) string {
	return formatEdited(d, "Z,ZZZ,ZZ9.99")
}
func formatIntEd(d decimal.Decimal) string {
	return formatEdited(d, "ZZZ,ZZZ,ZZ9.99")
}
func formatTotalEd(d decimal.Decimal) string {
	return formatEdited(d, "ZZ,ZZZ,ZZZ,ZZ9.99")
}

func parseDigits(s string, scale int32) decimal.Decimal {
	trim := strings.TrimSpace(s)
	if trim == "" {
		return decimal.NewFromInt(0)
	}
	// digits only, may have leading zeros
	// parse as int64
	var n int64 = 0
	for _, c := range trim {
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		}
	}
	return decimal.New(n, -scale)
}

func loadLoanFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// file not found -> treat as empty
		loanFileLines = []string{}
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// Scanner default max 64k, ok for 21 bytes
	// Allow longer lines
	for sc.Scan() {
		line := sc.Text()
		// Remove trailing \r if present (scanner already strips \n, but \r remains if CRLF)
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		loanFileLines = append(loanFileLines, line)
	}
}

func READPARA() {
	if !loanFileOpen {
		// should be open
	}
	if loanFileIndex >= len(loanFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := loanFileLines[loanFileIndex]
	loanFileIndex++
	// pad with spaces to 21
	if len(raw) < 21 {
		raw = raw + strings.Repeat(" ", 21-len(raw))
	} else if len(raw) > 21 {
		raw = raw[:21]
	}
	loanRec.LrAcct = raw[0:6]
	loanRec.LrPrincipal = parseDigits(raw[6:15], 2)
	loanRec.LrRate = parseDigits(raw[15:19], 2)
	yrStr := raw[19:21]
	yrTrim := strings.TrimSpace(yrStr)
	if yrTrim == "" {
		loanRec.LrYears = 0
	} else {
		var v int64
		for _, c := range yrTrim {
			if c >= '0' && c <= '9' {
				v = v*10 + int64(c-'0')
			}
		}
		loanRec.LrYears = v
	}
}

func PROCESSPARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	yearsDec := decimal.NewFromInt(loanRec.LrYears)
	prod := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(yearsDec)
	// divide by 100
	val := prod.Shift(-2)
	// ROUNDED to scale of target (2)
	val = val.Round(2)
	// overflow truncation to 9(9)V99
	val = truncateToScale(val, 2, 9)
	WsInterest = val

	// ADD WS-INTEREST TO WS-TOTAL
	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = truncateToScale(WsTotal, 2, 11)

	// ADD 1 TO WS-COUNT
	WsCount++
	// keep low-order 5 digits
	if WsCount > 99999 {
		WsCount = WsCount % 100000
	}

	WsPrinEd = formatPrinEd(loanRec.LrPrincipal)
	WsIntEd = formatIntEd(WsInterest)
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatTotalEd(WsTotal)
	// WS-COUNT is PIC 9(5) zero padded
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func MAINPARA() {
	// OPEN INPUT LOAN-FILE
	loadLoanFile()
	loanFileIndex = 0
	loanFileOpen = true
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	loanFileOpen = false
	SUMMARYPARA()
}

func main() {
	MAINPARA()
}
